func expandDesignCenterPolicyApplyConditions(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (interface{}, error) {
	if v == nil {
		return nil, nil
	}
	l := v.([]interface{})
	req := make([]interface{}, 0, len(l))
	for _, raw := range l {
		if raw == nil {
			continue
		}
		original := raw.(map[string]interface{})
		transformed := make(map[string]interface{})

		transformedConditionKey, err := expandDesignCenterPolicyApplyConditionsConditionKey(original["condition_key"], d, config)
		if err != nil {
			return nil, err
		} else if val := reflect.ValueOf(transformedConditionKey); val.IsValid() && !tpgresource.IsEmptyValue(val) {
			transformed["conditionKey"] = transformedConditionKey
		}

		transformedConditionValue, err := expandDesignCenterPolicyApplyConditionsConditionValue(original["condition_value"], d, config)
		if err != nil {
			return nil, err
		} else if val := reflect.ValueOf(transformedConditionValue); val.IsValid() && !tpgresource.IsEmptyValue(val) {
			transformed["conditionValue"] = transformedConditionValue
		}

		req = append(req, transformed)
	}
	return req, nil
}

